
const SOUNDS = [{"id":"bruh","name":"Bruh Sound","color":"linear-gradient(135deg, #8b5cf6, #6d28d9)","svg":"<svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"none\" stroke=\"#ffffff\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"11 5 6 9 2 9 2 15 6 15 11 19 11 5\"></polygon><path d=\"M15.54 8.46a5 5 0 0 1 0 7.07\"></path><path d=\"M19.07 4.93a10 10 0 0 1 0 14.14\"></path></svg>","hasTake":true,"origB64":"","takeB64":""},{"id":"reverb","name":"Fart Reverb","color":"linear-gradient(135deg, #ec4899, #be185d)","svg":"<svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"none\" stroke=\"#ffffff\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12.8 19.6A2 2 0 1 0 14 16H2\"></path><path d=\"M17.5 15.6A3 3 0 1 0 19 10H2\"></path><path d=\"M9.8 4.4A2 2 0 1 1 11 8H2\"></path></svg>","hasTake":true,"origB64":"","takeB64":""},{"id":"vineboom","name":"Vine Boom","color":"linear-gradient(135deg, #f59e0b, #d97706)","svg":"<svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"none\" stroke=\"#ffffff\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"13 2 3 14 12 14 11 22 21 10 12 10 13 2\"></polygon></svg>","hasTake":false,"origB64":"","takeB64":""},{"id":"wow","name":"Anime Wow","color":"linear-gradient(135deg, #06b6d4, #0284c7)","svg":"<svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"none\" stroke=\"#ffffff\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"m12 3-1.9 5.8a2 2 0 0 1-1.3 1.3L3 12l5.8 1.9a2 2 0 0 1 1.3 1.3L12 21l1.9-5.8a2 2 0 0 1 1.3-1.3L21 12l-5.8-1.9a2 2 0 0 1-1.3-1.3Z\"></path></svg>","hasTake":false,"origB64":"","takeB64":""},{"id":"emotional","name":"Emotional","color":"linear-gradient(135deg, #ef4444, #dc2626)","svg":"<svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"none\" stroke=\"#ffffff\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M19 14c1.49-1.46 3-3.21 3-5.5A5.5 5.5 0 0 0 16.5 3c-1.76 0-3 .5-4.5 2-1.5-1.5-2.74-2-4.5-2A5.5 5.5 0 0 0 2 8.5c0 2.3 1.5 4.05 3 5.5l7 7Z\"></path><path d=\"m12 13-1-1 2-2-3-3 2-2\"></path></svg>","hasTake":false,"origB64":"","takeB64":""},{"id":"oneup","name":"1-Up Retro","color":"linear-gradient(135deg, #10b981, #047857)","svg":"<svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"none\" stroke=\"#ffffff\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><line x1=\"6\" x2=\"10\" y1=\"12\" y2=\"12\"></line><line x1=\"8\" x2=\"8\" y1=\"10\" y2=\"14\"></line><line x1=\"15\" x2=\"15.01\" y1=\"13\" y2=\"13\"></line><line x1=\"18\" x2=\"18.01\" y1=\"11\" y2=\"11\"></line><rect width=\"20\" height=\"12\" x=\"2\" y=\"6\" rx=\"6\"></rect></svg>","hasTake":false,"origB64":"","takeB64":""}];
const STICKERS = [{"id":"speed","name":"Speed Laugh","file":"stickers/speed-laugh.gif","text":"HAHAHA!","soundB64":""},{"id":"streamer","name":"Streamer Rage","file":"stickers/streamer.gif","text":"LET'S GO!","soundB64":""},{"id":"meme1","name":"Meme Special","file":"stickers/meme1.webp","text":"OMG!","soundB64":""}];

let volume = 0.8;
let isMuted = false;
let previousVol = 0.8;
let isCooldown = false;
const COOLDOWN_MS = 2500;
let soundModes = {}; // 'orig' vs 'take'

let audioCtx = null;
function getAudioContext() {
	if (!audioCtx) {
		const AudioCtx = window.AudioContext || window.webkitAudioContext;
		if (AudioCtx) audioCtx = new AudioCtx();
	}
	if (audioCtx && audioCtx.state === 'suspended') {
		audioCtx.resume();
	}
	return audioCtx;
}

// Render 6 Pure Circular Buzzers with Vector Icons
function renderBuzzers() {
	const grid = document.getElementById('buzzer-grid');
	if (!grid) return;
	grid.innerHTML = '';

	SOUNDS.forEach((sound) => {
		soundModes[sound.id] = 'orig';

		const unit = document.createElement('div');
		unit.className = 'buzzer-unit';
		unit.id = 'buzzer-' + sound.id;

		// Circular Buzzer Button with clean SVG vector
		const circle = document.createElement('div');
		circle.className = 'buzzer-circle';
		circle.style.setProperty('--btn-color', sound.color);
		circle.innerHTML = sound.svg;
		unit.appendChild(circle);

		// Title
		const title = document.createElement('div');
		title.className = 'buzzer-title';
		title.textContent = sound.name;
		unit.appendChild(title);

		// Take switcher if sound has mimic take
		if (sound.hasTake) {
			const pill = document.createElement('div');
			pill.className = 'take-pill';

			const btnOrig = document.createElement('button');
			btnOrig.className = 'take-opt active';
			btnOrig.textContent = 'Orig';

			const btnTake = document.createElement('button');
			btnTake.className = 'take-opt';
			btnTake.textContent = 'Take 🎙️';

			btnOrig.addEventListener('click', (e) => {
				e.stopPropagation();
				soundModes[sound.id] = 'orig';
				btnOrig.classList.add('active');
				btnTake.classList.remove('active');
				setStatus(sound.name + ' (Original)');
			});

			btnTake.addEventListener('click', (e) => {
				e.stopPropagation();
				soundModes[sound.id] = 'take';
				btnTake.classList.add('active');
				btnOrig.classList.remove('active');
				setStatus(sound.name + " (Streamer's Take)");
			});

			pill.appendChild(btnOrig);
			pill.appendChild(btnTake);
			unit.appendChild(pill);
		}

		unit.addEventListener('click', () => triggerSound(sound));
		grid.appendChild(unit);
	});
}

// Render 3 Square Stickers / GIFs
function renderStickers() {
	const grid = document.getElementById('sticker-grid');
	if (!grid) return;
	grid.innerHTML = '';

	STICKERS.forEach((st) => {
		const card = document.createElement('div');
		card.className = 'sticker-card';
		card.id = 'sticker-' + st.id;

		const img = document.createElement('img');
		img.className = 'sticker-img';
		img.src = st.file;
		img.alt = st.name;

		const overlay = document.createElement('div');
		overlay.className = 'sticker-overlay';
		overlay.textContent = st.name;

		card.appendChild(img);
		card.appendChild(overlay);

		card.addEventListener('click', () => triggerSticker(st));
		grid.appendChild(card);
	});
}

function triggerSound(sound) {
	if (isCooldown) {
		setStatus('⏱️ Cooldown active. Please wait!');
		return;
	}

	const mode = soundModes[sound.id] || 'orig';
	const b64 = mode === 'take' && sound.takeB64 ? sound.takeB64 : sound.origB64;
	const modeText = mode === 'take' ? "Take" : "Orig";

	const unit = document.getElementById('buzzer-' + sound.id);
	if (unit) {
		unit.classList.add('active-pop');
		setTimeout(() => unit.classList.remove('active-pop'), 350);
	}

	playAudio(b64);
	setStatus('🔊 Played ' + sound.name + ' [' + modeText + ']');
	startCooldown();
}

function triggerSticker(st) {
	if (isCooldown) {
		setStatus('⏱️ Cooldown active. Please wait!');
		return;
	}

	const card = document.getElementById('sticker-' + st.id);
	if (card) {
		card.classList.add('active-pop');
		setTimeout(() => card.classList.remove('active-pop'), 400);

		const pop = document.createElement('div');
		pop.className = 'float-pop';
		pop.textContent = st.text;
		card.appendChild(pop);
		setTimeout(() => pop.remove(), 500);
	}

	playAudio(st.soundB64);
	setStatus('✨ Reacted with ' + st.name);
	startCooldown();
}

function playAudio(b64) {
	if (isMuted || volume <= 0) return;
	getAudioContext();

	if (b64) {
		try {
			const audio = new Audio('data:audio/mp3;base64,' + b64);
			audio.volume = volume;
			audio.play().catch(() => playSynth(320));
		} catch (e) {
			playSynth(320);
		}
	} else {
		playSynth(440);
	}
}

function playSynth(freq) {
	try {
		const ctx = getAudioContext();
		if (!ctx) return;
		const osc = ctx.createOscillator();
		const gain = ctx.createGain();
		osc.type = 'triangle';
		osc.frequency.setValueAtTime(freq, ctx.currentTime);
		gain.gain.setValueAtTime(volume * 0.25, ctx.currentTime);
		gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.25);
		osc.connect(gain);
		gain.connect(ctx.destination);
		osc.start();
		osc.stop(ctx.currentTime + 0.25);
	} catch (e) {}
}

function startCooldown() {
	isCooldown = true;
	const pill = document.getElementById('cooldown-text');
	if (pill) {
		pill.classList.add('active');
		pill.textContent = 'Wait 2.5s';
	}

	let remaining = COOLDOWN_MS / 1000;
	const timer = setInterval(() => {
		remaining -= 0.5;
		if (remaining > 0) {
			if (pill) pill.textContent = 'Wait ' + remaining.toFixed(1) + 's';
		} else {
			clearInterval(timer);
			isCooldown = false;
			if (pill) {
				pill.classList.remove('active');
				pill.textContent = 'Ready';
			}
		}
	}, 500);
}

function setStatus(msg) {
	const el = document.getElementById('status-text');
	if (el) el.textContent = msg;
}

function setVolume(val) {
	volume = parseFloat(val);
	isMuted = volume === 0;
	updateVolUI();
}

function toggleMute() {
	if (isMuted) {
		isMuted = false;
		volume = previousVol > 0 ? previousVol : 0.8;
	} else {
		previousVol = volume;
		isMuted = true;
		volume = 0;
	}
	updateVolUI();
}

function updateVolUI() {
	const volText = document.getElementById('vol-text');
	const slider = document.getElementById('vol-slider');
	const muteBtn = document.getElementById('btn-mute');

	if (volText) volText.textContent = isMuted ? 'Muted' : Math.round(volume * 100) + '%';
	if (slider) slider.value = volume;
	if (muteBtn) muteBtn.textContent = isMuted ? '🔇' : (volume > 0.5 ? '🔊' : '🔉');
}

document.addEventListener('DOMContentLoaded', () => {
	renderBuzzers();
	renderStickers();

	const slider = document.getElementById('vol-slider');
	if (slider) slider.addEventListener('input', (e) => setVolume(e.target.value));

	const mute = document.getElementById('btn-mute');
	if (mute) mute.addEventListener('click', toggleMute);

	if (window.Twitch && window.Twitch.ext) {
		window.Twitch.ext.onAuthorized((auth) => {
			setStatus('Connected to channel (' + auth.channelId.slice(-4) + ')');
		});
	}
});
